import re

def trump_detector(speech):
    vowels = "aeiou"
    count = 0
    i = 0
    while i < len(speech):
        if speech[i].lower() in vowels:
            start = i
            while i < len(speech) and speech[i].lower() == speech[start].lower():
                i += 1
            count += i - start - 1
        else:
            i += 1
    total_vowels = sum(speech.lower().count(vowel) for vowel in vowels)
    if total_vowels == 0:
        return 0
    return round(count / total_vowels, 2)
